    def __init__(self, window):
        self._win = window

    @property
    def _submit_button(self):
        return self._win.locator(
            auto_id="btnSubmit",
            fallback=[
                {"auto_id": "btnSave"},
                {"title": "Submit"},
            ],
        )

    def submit(self):
        self._submit_button.click()
